async (page) => {
  const checks = [];
  const check = (condition, message) => { if (!condition) throw new Error(message); checks.push(message); };
  const read = () => page.evaluate(() => JSON.parse(localStorage.getItem('phyqgen.prototype.v1')));
  await page.goto('http://127.0.0.1:5173/question-bank?question_id=3');
  await page.getByRole('dialog', { name: '习题详情与教师人工审核' }).waitFor();
  await page.getByRole('dialog').getByRole('button', { name: '修改草稿', exact: true }).click();
  let editor = page.getByRole('dialog', { name: '教师修改习题' });
  await editor.locator('input').first().fill('浏览器验收：能量转化题');
  await editor.getByRole('button', { name: '保存为新版本' }).click();
  await editor.waitFor({ state: 'hidden' });
  let q = (await read()).questions.find(q => q.id === 3);
  check(q.version === 2 && q.teacher_status === 'pending', '编辑草稿创建v2并保持待教师审核');
  await page.getByRole('dialog').getByRole('button', { name: '确认定稿', exact: true }).click();
  await page.getByRole('button', { name: '确认当前版本定稿' }).click();
  await page.getByText('v2 已由教师确认，可导出定稿').waitFor();
  q = (await read()).questions.find(q => q.id === 3);
  check(q.teacher_status === 'confirmed' && q.confirmations.some(c => c.version === 2), '教师确认记录关联v2');
  const downloaded = page.waitForEvent('download');
  await page.getByRole('button', { name: '导出定稿 TXT', exact: true }).click();
  const download = await downloaded;
  await download.saveAs('output/playwright/review-confirmed-v2.txt');
  checks.push('确认版本TXT真实下载成功');
  await page.getByRole('dialog').getByRole('button', { name: '修改草稿', exact: true }).click();
  editor = page.getByRole('dialog', { name: '教师修改习题' });
  await editor.locator('.el-form-item').filter({ hasText: /^答案/ }).locator('textarea').fill('');
  await editor.getByRole('button', { name: '保存为新版本' }).click();
  await editor.waitFor({ state: 'hidden' });
  q = (await read()).questions.find(q => q.id === 3);
  check(q.version === 3 && q.teacher_status === 'pending' && q.confirmations.length === 1, '修改定稿创建v3，旧确认仅对v2有效');
  await page.getByRole('dialog').getByRole('button', { name: '确认定稿', exact: true }).click();
  await page.getByRole('button', { name: '确认当前版本定稿' }).click();
  await page.getByText('请先补全答案', { exact: true }).waitFor();
  check((await read()).questions.find(q => q.id === 3).teacher_status === 'pending', '缺少答案时阻止定稿');
  await page.getByRole('dialog').getByRole('button', { name: '修改草稿', exact: true }).click();
  editor = page.getByRole('dialog', { name: '教师修改习题' });
  await editor.locator('.el-form-item').filter({ hasText: /^答案/ }).locator('textarea').fill('$v=10\\,\\mathrm{m/s}$。');
  await editor.getByRole('button', { name: '移除当前配图' }).click();
  await editor.getByRole('button', { name: '保存为新版本' }).click();
  await editor.waitFor({ state: 'hidden' });
  await page.getByRole('dialog').getByRole('button', { name: '确认定稿', exact: true }).click();
  await page.getByRole('button', { name: '确认当前版本定稿' }).click();
  await page.getByText('此题要求配图，请先补充可预览的图片', { exact: true }).waitFor();
  checks.push('要求配图但缺图时阻止定稿');
  await page.getByRole('dialog').getByRole('button', { name: '修改草稿', exact: true }).click();
  editor = page.getByRole('dialog', { name: '教师修改习题' });
  await editor.locator('input[type=file]').setInputFiles({ name: 'valid-test.png', mimeType: 'image/png', buffer: Buffer.from('iVBORw0KGgoAAAANSUhEUgAAAAEAAAABCAQAAAC1HAwCAAAAC0lEQVR42mP8/x8AAusB9Y9Z1xkAAAAASUVORK5CYII=', 'base64') });
  await page.getByText('已加载配图，请核对右侧预览后保存').waitFor();
  await editor.getByRole('button', { name: '保存为新版本' }).click();
  await editor.waitFor({ state: 'hidden' });
  await page.getByRole('dialog').getByRole('button', { name: '确认定稿', exact: true }).click();
  await page.getByRole('button', { name: '确认当前版本定稿' }).click();
  await page.getByText('v5 已由教师确认，可导出定稿').waitFor();
  check((await read()).questions.find(q => q.id === 3).illustration_url.startsWith('data:image/png'), '本地替换配图保存且可再次确认');
  await page.reload();
  await page.getByRole('dialog', { name: '习题详情与教师人工审核' }).waitFor();
  q = (await read()).questions.find(q => q.id === 3);
  check(q.version === 5 && q.teacher_status === 'confirmed', '刷新后版本、配图与确认记录保留');
  await page.screenshot({ path: 'output/playwright/02-review-confirmation.png' });
  return { checks, version: q.version, confirmations: q.confirmations.length };
}
